// math.js
export const add = (a, b) => a + b;
export async function fetchUser(id, http) {
  const res = await http.get(`/users/${id}`);
  if (!res.ok) throw new Error('not found');
  return res.data;
}

// math.test.js
import { test, describe, it, mock } from 'node:test';
import assert from 'node:assert/strict';
import { add, fetchUser } from './math.js';

describe('add', () => {
  it('adds numbers', () => assert.equal(add(2, 3), 5));
  it('handles negatives', () => assert.equal(add(-1, -1), -2));
});

test('fetchUser returns data', async () => {
  const http = { get: mock.fn(async () => ({ ok: true, data: { id: 1, name: 'Ann' } })) };
  assert.deepEqual(await fetchUser(1, http), { id: 1, name: 'Ann' });
  assert.equal(http.get.mock.callCount(), 1);
});

test('fetchUser rejects when missing', async () => {
  await assert.rejects(fetchUser(2, { get: async () => ({ ok: false }) }), /not found/);
});

// cart.test.js     npm i -D vitest     npx vitest run
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { total, checkout } from './cart.js';

describe('cart', () => {
  it.each([
    [[{ price: 10, qty: 2 }], 20],
    [[{ price: 5, qty: 1 }, { price: 7, qty: 3 }], 26],
    [[], 0],
  ])('total(%j) = %i', (items, expected) => {
    expect(total(items)).toBe(expected);
  });

  describe('checkout', () => {
    const payments = { charge: vi.fn() };
    beforeEach(() => payments.charge.mockReset());

    it('charges the total once', async () => {
      payments.charge.mockResolvedValue({ id: 'p_1' });
      const result = await checkout([{ price: 10, qty: 2 }], payments);
      expect(payments.charge).toHaveBeenCalledTimes(1);
      expect(payments.charge).toHaveBeenCalledWith(20);
      expect(result).toMatchObject({ paymentId: 'p_1' });
    });

    it('rejects when the payment fails', async () => {
      payments.charge.mockRejectedValue(new Error('declined'));
      await expect(checkout([{ price: 1, qty: 1 }], payments)).rejects.toThrow('declined');
    });
  });
});

// npm i -D supertest
import { test, before, after, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';
import app from '../src/app.js';
import { db } from '../src/lib/db.js';

before(async () => { await db.connect(process.env.TEST_DATABASE_URL); });
beforeEach(async () => { await db.reset(); });
after(async () => { await db.close(); });

test('POST /users creates a user', async () => {
  const res = await request(app)
    .post('/users')
    .send({ name: 'Ann', email: 'ann@example.com', password: 'a-long-password' })
    .expect(201)
    .expect('Content-Type', /json/);

  assert.equal(res.body.email, 'ann@example.com');
  assert.equal(res.body.password, undefined);        // never returned
});

test('POST /users rejects invalid email', async () => {
  const res = await request(app).post('/users').send({ name: 'Ann', email: 'nope' }).expect(422);
  assert.ok(res.body.error);
});

test('GET /me requires authentication', async () => {
  await request(app).get('/me').expect(401);
});

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import app from '../src/app.js';

let server, base;
before(() => new Promise((resolve) => {
  server = app.listen(0, () => { base = `http://127.0.0.1:${server.address().port}`; resolve(); });
}));
after(() => new Promise((resolve) => server.close(resolve)));

test('GET /health', async () => {
  const res = await fetch(`${base}/health`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { status: 'ok' });
});

import { test } from 'node:test';
import assert from 'node:assert/strict';

function debounce(fn, ms) {
  let id;
  return (...args) => { clearTimeout(id); id = setTimeout(() => fn(...args), ms); };
}

test('debounce calls once after the delay', (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });
  const spy = t.mock.fn();
  const d = debounce(spy, 200);

  d('a'); d('b'); d('c');
  t.mock.timers.tick(199);
  assert.equal(spy.mock.callCount(), 0);
  t.mock.timers.tick(1);
  assert.equal(spy.mock.callCount(), 1);
  assert.deepEqual(spy.mock.calls[0].arguments, ['c']);
});

test('sendWelcome calls the mailer', async (t) => {
  const mailer = { send: t.mock.fn(async () => true) };
  const service = { async register(email) { await mailer.send({ to: email, subject: 'Welcome' }); return { email }; } };

  await service.register('a@b.c');
  assert.equal(mailer.send.mock.callCount(), 1);
  assert.equal(mailer.send.mock.calls[0].arguments[0].to, 'a@b.c');
});
